    private static void add(int month,String rows){
        MONTHS.put(month,rows.split("\\|"));
    }
    public static String[] times(int month,int day) {
        String[] result={"—","12:15","—","—","—"};
        String[] rows=MONTHS.get(month);
        if(rows==null||day<1||day>rows.length)return result;
        String[] values=rows[day-1].trim().split("\\s+");
        if(values.length!=4)return result;
        int[] col={0,2,3,4};
        for(int i=0;i<4;i++) {
            if(values[i].equals("--"))continue;
            String[] parts=values[i].split("-");
            if(parts.length!=2)continue;
            try {
                int hr=Integer.parseInt(parts[0]),min=Integer.parseInt(parts[1]);
                if(i>0) hr+=12;
                if(hr>23||min>59)continue;
                result[col[i]]=String.format(Locale.US,"%02d:%02d",hr,min);
            } catch(NumberFormatException ignored){}
        }
        return result;
    }
